const allResults = $input.all().map(i => i.json);
const threshold = 80;
const lowScores = [];
const grades = { A: 0, B: 0, C: 0, D: 0, X: 0 };
let totalCritical = 0;
let totalIssues = 0;
let auditedCount = 0;
for (const r of allResults) {
  if (!r || !r.audit_summary) {
    grades.X++;
    continue;
  }
  auditedCount++;
  const g = r.audit_summary.grade || 'X';
  grades[g] = (grades[g] || 0) + 1;
  totalCritical += r.audit_summary.critical_count || 0;
  totalIssues += r.audit_summary.failed || 0;
  if ((r.audit_summary.score || 0) < threshold || (r.audit_summary.critical_count || 0) > 0) {
    lowScores.push({
      project_id: r.project_id,
      project_name: r.project_name,
      score: r.audit_summary.score,
      grade: g,
      critical_count: r.audit_summary.critical_count,
      warning_count: r.audit_summary.warning_count,
      issues_top: (r.issues || []).slice(0, 5).map(i => i.severity + ': ' + i.label)
    });
  }
}
lowScores.sort((a, b) => (a.score || 0) - (b.score || 0));
return [{ json: {
  audited_count: auditedCount,
  unauditable_count: grades.X,
  grades_distribution: grades,
  total_critical: totalCritical,
  total_issues: totalIssues,
  low_scores: lowScores,
  has_alerts: lowScores.length > 0
}}];

const r = $input.first().json;
const gradeColor = { A:'#27ae60', B:'#f1c40f', C:'#e67e22', D:'#e74c3c', X:'#666' };

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const rowsLow = (r.low_scores || []).map(p => `<tr style=\"background:${p.critical_count > 0 ? '#fee' : (p.score < 60 ? '#fff8e0' : '#fff')}\">
  <td>${esc(p.project_name)}</td>
  <td><span style=\"background:${gradeColor[p.grade]};color:white;padding:2px 10px;border-radius:10px;font-size:11px;font-weight:bold\">${p.grade}</span></td>
  <td style=\"text-align:right;font-weight:600\">${p.score}</td>
  <td style=\"text-align:right;color:#c00;font-weight:600\">${p.critical_count}</td>
  <td style=\"text-align:right\">${p.warning_count}</td>
  <td style=\"font-size:12px;color:#555\">${(p.issues_top || []).slice(0,3).join('<br>')}</td>
</tr>`).join('');

const gd = r.grades_distribution || {};
const html = `<div style=\"font-family:system-ui,sans-serif;color:#222;max-width:820px\">
<h2>Compliance Audit Semanal — ${r.audited_count} proyectos auditados</h2>
<p style=\"font-size:14px;color:#555\">Distribucion de grades: 
  <b style=\"color:#27ae60\">A=${gd.A||0}</b> · 
  <b style=\"color:#f1c40f\">B=${gd.B||0}</b> · 
  <b style=\"color:#e67e22\">C=${gd.C||0}</b> · 
  <b style=\"color:#e74c3c\">D=${gd.D||0}</b>${gd.X ? ' · sin auditar (error): ' + gd.X : ''}
</p>
<p style=\"font-size:14px;color:#555\">Total critical: <b style=\"color:#c00\">${r.total_critical}</b> · total issues: ${r.total_issues}</p>
<h3 style=\"margin-top:24px\">Proyectos con score &lt;80 o critical&gt;0 (${(r.low_scores || []).length})</h3>
<table style=\"width:100%;border-collapse:collapse;font-size:13px\"><thead><tr style=\"background:#f0f0f3\"><th align=\"left\">proyecto</th><th align=\"left\">grade</th><th align=\"right\">score</th><th align=\"right\">critical</th><th align=\"right\">warning</th><th align=\"left\">top issues</th></tr></thead><tbody>${rowsLow}</tbody></table>
<p style=\"font-size:12px;color:#888;margin-top:24px\">cron_compliance_audit_weekly - generado ${new Date().toISOString()}<br>Para audit individual: <code>curl -X POST -H 'x-api-key: XXX' -d '{\"project_id\":\"...\",\"send_email\":true}' https://n8n-n8n.zzeluw.easypanel.host/webhook/audit-project</code></p>
</div>`;

const subject = `[Compliance Semanal] ${r.audited_count} auditados, ${r.total_critical} critical, ${(r.low_scores || []).length} grade C/D`;
return [{ json: { html, subject } }];
